--region handler
---详情按钮点击回调
function UIWorldBossCardBonusNode:BtnDetailsOnClickHandler()
    local hasCard = cardComponent:IsHasCard(self.data.refId)
    if hasCard then
        local id = cardComponent:GetIdByCardId(self.data.refId)
        CardProgressionUtils.OpenDialog(Constants.UITypeIds.CultivateMain, {playerCardId = id, closeMainSceneOnFinalize = true}, UICommonUtils.GetShowDialogArguments())
    else
        local gachaponUtils = import('Game.Gachapon.GachaponUtils')
        gachaponUtils.OpenDetail(self.data.refId, {{id = Constants.UITypeIds.UIWorldBossMainDialog}}, {showJumpBtn = true, closeMainSceneOnFinalize = true}, UICommonUtils.GetShowDialogArguments())
    end
    UIModule.CloseDialogById(Constants.UITypeIds.UIWorldBossMainDialog)
end
--endregion handler

--region public
---刷新节点
function UIWorldBossCardBonusNode:RefreshNode(data)
    self.data = data
    ---@type CardHeadNode
    local scr = CfUtils.GetLuaScr(self.CommonSmallHeadNode, "Game.Behaviours.CardHeadNode")
    if isNull(scr) then return end

    if checkInt(data.type) ~= Constants.UpRoleBuffType.CardId then return end
    
    scr:FreshNodeByCardVo(data.refId, 1, false)
    --scr:FillUpInfo(true)

    local hasCard = cardComponent:IsHasCard(data.refId)
    CfUtils.SetUISwitchText(self.TxtDesc, hasCard and 1 or 2)
    CfUtils.SetActive(self.ImgMask, hasCard == false) 
    
    local vo = QuestConfMgr:GetInstance():GetQuestUpBuffVo(data.commonAddId)
    if vo then
        CfUtils.FillText(self.TxtDesc, vo.desc)
    end
end
--endregion public

